index 000000000..5da586070
--- /dev/null
+++ b/broker/claim/ASSUMPTIONS.md
@@ -0,0 +1,14 @@
+# Box claim: assumptions
+
+Built for CTRL-claim (BOARD.md) against SPEC HW-10 and HW-1 (D-102). Covers `broker/claim`, the claim gate in `broker/firstboot` (`ClaimedCard`) and the claim screen in `broker/localui`. Each row is a reading of the spec, with what changes if the reading is wrong.
+
+| # | Assumption | Spec basis | If it changes |
+|---|---|---|---|
+| K1 | **Code format.** The sticker code is 16 symbols from the Owner Card's alphabet (no I, O, 0 or 1), 80 bits, printed `XXXX-XXXX-XXXX-XXXX`. Typing ignores case, spaces and dashes. The seller makes it with `NewCode` and seals it with `Seal` when preloading the box; the sticker's QR may be a link to `/claim?code=…`, which only fills in the form. | HW-10 | A different sticker format changes `NewCode`, `Normalize` and the screen's placeholder only. |
+| K2 | **The box keeps no code.** The disk holds a salted SHA-256 verifier of the code (domain "agentos claim v1"), never the code. The claim removes the verifier and stores only a SHA-256 hash of the claimant token, so the sticker "unlocks nothing and dies at first claim". 80 bits under a 5-try lock make guessing hopeless even with the verifier read off the disk by the seller, who knows the code anyway. | HW-10 | — |
+| K3 | **Lockout survives restarts of the software, not of the box.** Every wrong code is saved before the answer goes out. After `MaxWrong` (5) the screen locks and records the kernel boot ID; only a new boot ID (the owner restarts the box) lifts it. Each lock halves the next boot's allowance (5, 2, then 1 per boot), so a thief who power-cycles gets at most a handful of guesses per restart. A save that fails locks the screen in memory (fail closed). This is the #1056 hint: the backoff is persisted. | HW-10 acceptance 3 | If the spec wants a time-based lock instead, `allowed` and the boot check change; the persisted counter stays. |
+| K4 | **No claim state means the download path.** `Open` returns `ErrNoCode` when the box was never sealed: a box installed from the GitHub flasher pairs by the flasher's one-time QR instead (FLASH-1). `Seal` refuses a box that already holds state, so a seller cannot reseal a claimed box without reinstalling. | HW-10 | — |
+| K5 | **No secret before the claim.** `firstboot.ClaimedCard` builds the card step (and so draws randomness for the Owner Card) only after the claim succeeds. Before it, `Hold` says the box waits to be claimed. The acceptance test scans a copy of the partition after a wrong code and a restart for anything drawn from a canary randomness stream, and checks none was drawn. | HW-10, HW-1 | — |
+| K6 | **Setup belongs to the claimant.** The claim sets an HttpOnly, SameSite=Strict cookie with the claimant token for the setup cookie's lifetime (7 days). While a claim is configured, `/`, `/setup` and every setup step redirect to `/claim` before the claim and refuse any phone without the token after it. A claimant who loses that phone before the card exists reinstalls (the "already claimed" path). | HW-10 | A recovery path for a lost claimant phone would be a new row. |
+| K7 | **The journal gets counts only.** Claim events are fixed strings plus try counts; a typed code never reaches the journal or logs. | HW-10, CRED-8 | — |
+| K8 | **Not wired.** agentosd does not open a claim or pass `ClaimedCard` to the local UI yet, and the card display is not mounted behind the claimant check. Wiring conditions: open the claim with `KernelBootID`; on `ErrNoCode` take the flasher path; give `localui.Config.Claim` the `ClaimedCard`; mount `ClaimedCard.Card()` behind `Claimant`. Release finding on the PR. | HW-10, HW-1 | — |
diff --git a/broker/claim/claim.go b/broker/claim/claim.go
new file mode 100644
index 000000000..930b37942
--- /dev/null
+++ b/broker/claim/claim.go
@@ -0,0 +1,350 @@
+// Package claim is a preloaded box's claim (HW-10): the seller writes a
+// one-time claim code to the box and prints it on a sticker; the first
+// phone to present it claims the box, the code is then burned, and every
+// later attempt is refused with "already claimed". The code unlocks
+// nothing: no secret exists before the claim (HW-1), and the first-boot
+// path generates the Owner Card only after it (firstboot.ClaimedCard).
+//
+// Wrong codes are counted on disk before the answer goes out; after
+// MaxWrong of them the claim screen locks until the box itself restarts
+// (a new kernel boot), so a daemon restart or a crash never resets it, and
+// each lock halves the tries the next boot allows (ASSUMPTIONS.md K3).
+package claim
+
+import (
+	"crypto/rand"
+	"crypto/sha256"
+	"crypto/subtle"
+	"encoding/hex"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"os"
+	"strings"
+	"sync"
+)
+
+// Store persists the claim state (change.FileStore, change.MemStore).
+type Store interface {
+	Load() ([]byte, error)
+	Save([]byte) error
+}
+
+// The claim's refusals. Their text is the claim screen's (CH-21).
+var (
+	ErrAlreadyClaimed = errors.New("claim: I am already claimed")
+	ErrWrongCode      = errors.New("claim: that is not my claim code")
+	ErrLocked         = errors.New("claim: too many wrong codes; restart me to try again")
+	ErrNoCode         = errors.New("claim: I hold no claim code")
+)
+
+// MaxWrong is the wrong codes the first boot allows before the screen locks.
+const MaxWrong = 5
+
+// CodeSymbols is the claim code's length: 16 symbols of 5 bits (80 bits),
+// printed in four groups of four.
+const CodeSymbols = 16
+
+// alphabet is the Owner Card's (broker/card C1): no I, O, 0 or 1.
+const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
+
+// Journal events. Fixed strings and counts only: never the typed code.
+const (
+	EventSealed   = "claim: code sealed by the seller flow"
+	EventClaimed  = "claim: box claimed; code burned"
+	EventAgain    = "claim: refused, already claimed"
+	EventWrong    = "claim: wrong code"
+	EventLocked   = "claim: screen locked after wrong codes"
+	EventRefused  = "claim: refused while locked"
+	EventUnlocked = "claim: screen unlocked by a restart"
+)
+
+// state is everything the claim keeps on disk. It holds no secret: the
+// code only as a salted hash, removed at the claim, and the claimant's
+// token only as a hash.
+type state struct {
+	Salt     []byte `json:"salt,omitempty"`
+	Verifier []byte `json:"verifier,omitempty"`
+	Claimed  bool   `json:"claimed"`
+	Owner    []byte `json:"owner,omitempty"`
+	// Wrong counts wrong codes since the screen last unlocked; Total all
+	// of them. Locks counts locks, so each boot after one allows fewer.
+	Wrong int `json:"wrong"`
+	Total int `json:"total"`
+	Locks int `json:"locks"`
+	// LockedBoot is the kernel boot the screen locked in; "" when open.
+	LockedBoot string `json:"locked_boot,omitempty"`
+}
+
+// Config configures Open. Store is required.
+type Config struct {
+	Store Store
+	// BootID names the current kernel boot; KernelBootID when nil. A lock
+	// lifts only when it changes.
+	BootID func() (string, error)
+	// Journal records attempts (fixed strings with counts).
+	Journal func(event string)
+	// Rand makes the claimant's token; crypto/rand.Reader when nil.
+	Rand io.Reader
+}
+
+// Claim is the box's claim state.
+type Claim struct {
+	mu      sync.Mutex
+	st      state
+	store   Store
+	journal func(string)
+	rand    io.Reader
+	boot    string
+	// stuck is set when a wrong count could not be saved: the screen
+	// stays locked for this process (fail closed).
+	stuck bool
+}
+
+// KernelBootID reads Linux's boot_id, which changes on every boot.
+func KernelBootID() (string, error) {
+	b, err := os.ReadFile("/proc/sys/kernel/random/boot_id")
+	if err != nil {
+		return "", err
+	}
+	id := strings.TrimSpace(string(b))
+	if id == "" {
+		return "", errors.New("claim: empty boot_id")
+	}
+	return id, nil
+}
+
+// NewCode makes a claim code for the seller flow, grouped XXXX-XXXX-XXXX-XXXX.
+func NewCode(r io.Reader) (string, error) {
+	if r == nil {
+		r = rand.Reader
+	}
+	var sb strings.Builder
+	buf := make([]byte, 1)
+	for i := 0; i < CodeSymbols; {
+		if _, err := io.ReadFull(r, buf); err != nil {
+			return "", err
+		}
+		// 256 is a multiple of 32: no bias.
+		if i > 0 && i%4 == 0 {
+			sb.WriteByte('-')
+		}
+		sb.WriteByte(alphabet[buf[0]%32])
+		i++
+	}
+	return sb.String(), nil
+}
+
+// Normalize is the typed code as the box compares it: upper case, without
+// spaces or dashes.
+func Normalize(s string) string {
+	s = strings.ToUpper(s)
+	var b strings.Builder
+	for _, r := range s {
+		switch r {
+		case ' ', '-', '\t':
+			continue
+		}
+		b.WriteRune(r)
+	}
+	return b.String()
+}
+
+// Seal is the seller flow's write: the box keeps the code as a salted
+// hash only. It refuses a box that already holds a claim state.
+func Seal(st Store, code string, r io.Reader, journal func(string)) error {
+	if r == nil {
+		r = rand.Reader
+	}
+	if b, err := st.Load(); err != nil {
+		return err
+	} else if b != nil {
+		return errors.New("claim: I already hold a claim state")
+	}
+	c := Normalize(code)
+	if len(c) != CodeSymbols || strings.Trim(c, alphabet) != "" {
+		return errors.New("claim: not a claim code")
+	}
+	s := state{Salt: make([]byte, 16)}
+	if _, err := io.ReadFull(r, s.Salt); err != nil {
+		return err
+	}
+	s.Verifier = verifier(s.Salt, c)
+	b, err := json.Marshal(s)
+	if err != nil {
+		return err
+	}
+	if err := st.Save(b); err != nil {
+		return err
+	}
+	if journal != nil {
+		journal(EventSealed)
+	}
+	return nil
+}
+
+func verifier(salt []byte, code string) []byte {
+	h := sha256.New()
+	h.Write([]byte("agentos claim v1\x00"))
+	h.Write(salt)
+	h.Write([]byte(code))
+	return h.Sum(nil)
+}
+
+func tokenHash(tok string) []byte {
+	h := sha256.Sum256([]byte("agentos claimant v1\x00" + tok))
+	return h[:]
+}
+
+// Open loads the claim state. ErrNoCode means the box was never sealed
+// (the download path, HW-10, which pairs by the flasher's QR instead). A
+// lock from an earlier boot lifts here.
+func Open(cfg Config) (*Claim, error) {
+	if cfg.Store == nil {
+		return nil, errors.New("claim: no store")
+	}
+	if cfg.BootID == nil {
+		cfg.BootID = KernelBootID
+	}
+	if cfg.Journal == nil {
+		cfg.Journal = func(string) {}
+	}
+	if cfg.Rand == nil {
+		cfg.Rand = rand.Reader
+	}
+	boot, err := cfg.BootID()
+	if err != nil {
+		return nil, fmt.Errorf("claim: boot id: %w", err)
+	}
+	b, err := cfg.Store.Load()
+	if err != nil {
+		return nil, err
+	}
+	if b == nil {
+		return nil, ErrNoCode
+	}
+	c := &Claim{store: cfg.Store, journal: cfg.Journal, rand: cfg.Rand, boot: boot}
+	if err := json.Unmarshal(b, &c.st); err != nil {
+		return nil, fmt.Errorf("claim: state: %w", err)
+	}
+	if !c.st.Claimed && len(c.st.Verifier) != sha256.Size {
+		return nil, errors.New("claim: state holds neither a code nor a claim")
+	}
+	if c.st.LockedBoot != "" && c.st.LockedBoot != boot {
+		c.st.LockedBoot = ""
+		c.st.Wrong = 0
+		if err := c.save(); err != nil {
+			return nil, err
+		}
+		c.journal(EventUnlocked)
+	}
+	return c, nil
+}
+
+func (c *Claim) save() error {
+	b, err := json.Marshal(c.st)
+	if err != nil {
+		return err
+	}
+	return c.store.Save(b)
+}
+
+// allowed is the wrong codes this boot allows: MaxWrong, halved per lock,
+// at least one.
+func (c *Claim) allowed() int {
+	n := MaxWrong
+	for i := 0; i < c.st.Locks && n > 1; i++ {
+		n /= 2
+	}
+	return n
+}
+
+func (c *Claim) lockedLocked() bool { return c.stuck || c.st.LockedBoot != "" }
+
+// Status is what the claim screen shows.
+type Status struct {
+	Claimed bool
+	Locked  bool
+	// TriesLeft is the wrong codes still allowed before the screen locks.
+	TriesLeft int
+}
+
+// Status reports the claim's state.
+func (c *Claim) Status() Status {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	s := Status{Claimed: c.st.Claimed, Locked: !c.st.Claimed && c.lockedLocked()}
+	if !s.Claimed && !s.Locked {
+		s.TriesLeft = c.allowed() - c.st.Wrong
+	}
+	return s
+}
+
+// Claimed reports whether the box is claimed.
+func (c *Claim) Claimed() bool { c.mu.Lock(); defer c.mu.Unlock(); return c.st.Claimed }
+
+// Try presents a code. The right code on an unclaimed, unlocked box
+// claims it: the code is burned and the returned token names the phone
+// that claimed it (Claimant). The claim is saved before Try returns; if
+// the save fails the box stays unclaimed.
+func (c *Claim) Try(code string) (string, error) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	if c.st.Claimed {
+		c.journal(EventAgain)
+		return "", ErrAlreadyClaimed
+	}
+	if c.lockedLocked() {
+		c.journal(EventRefused)
+		return "", ErrLocked
+	}
+	got := verifier(c.st.Salt, Normalize(code))
+	if subtle.ConstantTimeCompare(got, c.st.Verifier) != 1 {
+		allow := c.allowed()
+		c.st.Wrong++
+		c.st.Total++
+		locked := c.st.Wrong >= allow
+		if locked {
+			c.st.LockedBoot = c.boot
+			c.st.Locks++
+		}
+		// The count is on disk before the answer goes out, so a crash or
+		// a daemon restart never gives tries back.
+		if err := c.save(); err != nil {
+			c.stuck = true
+			c.journal(EventLocked)
+			return "", fmt.Errorf("%w (%v)", ErrLocked, err)
+		}
+		c.journal(fmt.Sprintf("%s (%d of %d, %d in all)", EventWrong, c.st.Wrong, allow, c.st.Total))
+		if locked {
+			c.journal(EventLocked)
+			return "", ErrLocked
+		}
+		return "", ErrWrongCode
+	}
+	tb := make([]byte, 32)
+	if _, err := io.ReadFull(c.rand, tb); err != nil {
+		return "", err
+	}
+	tok := hex.EncodeToString(tb)
+	prev := c.st
+	c.st = state{Claimed: true, Owner: tokenHash(tok), Total: prev.Total, Locks: prev.Locks}
+	if err := c.save(); err != nil {
+		c.st = prev
+		return "", err
+	}
+	c.journal(EventClaimed)
+	return tok, nil
+}
+
+// Claimant reports whether tok is the token of the phone that claimed the
+// box.
+func (c *Claim) Claimant(tok string) bool {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	if !c.st.Claimed || len(tok) != 64 {
+		return false
+	}
+	return subtle.ConstantTimeCompare(tokenHash(tok), c.st.Owner) == 1
+}
diff --git a/broker/claim/claim_test.go b/broker/claim/claim_test.go
new file mode 100644
index 000000000..e5d3a9aa8
--- /dev/null
+++ b/broker/claim/claim_test.go
@@ -0,0 +1,393 @@
+package claim
+
+// REQ: HW-10
+
+import (
+	"bytes"
+	"encoding/json"
+	"errors"
+	mrand "math/rand"
+	"os"
+	"path/filepath"
+	"strconv"
+	"strings"
+	"testing"
+
+	"github.com/ghbmrk/agentos/broker/change"
+)
+
+// box is one preloaded box's claim state on disk, opened per start.
+type box struct {
+	t       *testing.T
+	st      change.FileStore
+	boot    string
+	journal []string
+}
+
+func newBox(t *testing.T) (*box, string) {
+	t.Helper()
+	b := &box{t: t, st: change.FileStore{Path: filepath.Join(t.TempDir(), "claim.json")}, boot: "boot-1"}
+	code, err := NewCode(nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := Seal(b.st, code, nil, nil); err != nil {
+		t.Fatal(err)
+	}
+	return b, code
+}
+
+// start opens the claim as the daemon does on each start.
+func (b *box) start() *Claim {
+	b.t.Helper()
+	c, err := Open(Config{Store: b.st, BootID: func() (string, error) { return b.boot, nil },
+		Journal: func(e string) { b.journal = append(b.journal, e) }})
+	if err != nil {
+		b.t.Fatal(err)
+	}
+	return c
+}
+
+func wrongCode(code string) string {
+	if code[0] == 'A' {
+		return "B" + code[1:]
+	}
+	return "A" + code[1:]
+}
+
+// Acceptance 1: a second claim on a claimed box is refused with "already
+// claimed", also with the right code and after a restart.
+func TestSecondClaimRefusedAlreadyClaimed(t *testing.T) {
+	b, code := newBox(t)
+	c := b.start()
+	tok, err := c.Try(strings.ToLower(strings.ReplaceAll(code, "-", " ")))
+	if err != nil {
+		t.Fatalf("first claim: %v", err)
+	}
+	if !c.Claimant(tok) || c.Claimant(strings.Repeat("0", 64)) {
+		t.Fatal("claimant token does not name the claiming phone alone")
+	}
+	if _, err := c.Try(code); !errors.Is(err, ErrAlreadyClaimed) {
+		t.Fatalf("second claim, same start: %v", err)
+	}
+	b.boot = "boot-2"
+	c = b.start()
+	for _, try := range []string{code, wrongCode(code), ""} {
+		if _, err := c.Try(try); !errors.Is(err, ErrAlreadyClaimed) {
+			t.Fatalf("claim %q after restart: %v", try, err)
+		}
+	}
+	if !c.Claimant(tok) {
+		t.Fatal("claimant lost across restart")
+	}
+	if st := c.Status(); !st.Claimed || st.Locked {
+		t.Fatalf("status %+v", st)
+	}
+	if !strings.Contains(ErrAlreadyClaimed.Error(), "already claimed") {
+		t.Fatal("refusal text")
+	}
+}
+
+// The code is burned: after the claim neither the code nor its hash is on
+// disk; before it the code is there as a salted hash only.
+func TestCodeKeptHashedAndBurnedAtClaim(t *testing.T) {
+	b, code := newBox(t)
+	raw, _ := os.ReadFile(b.st.Path)
+	if bytes.Contains(raw, []byte(code)) || bytes.Contains(raw, []byte(Normalize(code))) {
+		t.Fatal("claim code in plaintext on disk")
+	}
+	c := b.start()
+	if _, err := c.Try(code); err != nil {
+		t.Fatal(err)
+	}
+	raw, _ = os.ReadFile(b.st.Path)
+	if bytes.Contains(raw, []byte("verifier")) || bytes.Contains(raw, []byte("salt")) {
+		t.Fatalf("code hash kept after claim: %s", raw)
+	}
+}
+
+// Two phones racing with the right code: exactly one claims the box.
+func TestRacingClaimsOneWins(t *testing.T) {
+	b, code := newBox(t)
+	c := b.start()
+	res := make(chan error, 8)
+	for i := 0; i < 8; i++ {
+		go func() { _, err := c.Try(code); res <- err }()
+	}
+	wins := 0
+	for i := 0; i < 8; i++ {
+		err := <-res
+		switch {
+		case err == nil:
+			wins++
+		case !errors.Is(err, ErrAlreadyClaimed):
+			t.Fatal(err)
+		}
+	}
+	if wins != 1 {
+		t.Fatalf("%d claims won", wins)
+	}
+}
+
+// Acceptance 3: a wrong code is refused and counted; MaxWrong wrong codes
+// lock the screen, and the lock holds, the right code included, until
+// the box restarts. A daemon restart (same kernel boot) does not lift it
+// (the #1056 hint: the lockout persists across restarts).
+func TestWrongCodesLockUntilBoxRestarts(t *testing.T) {
+	b, code := newBox(t)
+	c := b.start()
+	for i := 1; i < MaxWrong; i++ {
+		if _, err := c.Try(wrongCode(code)); !errors.Is(err, ErrWrongCode) {
+			t.Fatalf("wrong code %d: %v", i, err)
+		}
+		if got := c.Status().TriesLeft; got != MaxWrong-i {
+			t.Fatalf("tries left %d after %d wrong", got, i)
+		}
+	}
+	// A daemon restart mid-count gives no tries back.
+	c = b.start()
+	if got := c.Status().TriesLeft; got != 1 {
+		t.Fatalf("tries left after daemon restart: %d", got)
+	}
+	if _, err := c.Try(wrongCode(code)); !errors.Is(err, ErrLocked) {
+		t.Fatalf("last wrong code: %v", err)
+	}
+	if _, err := c.Try(code); !errors.Is(err, ErrLocked) {
+		t.Fatalf("right code while locked: %v", err)
+	}
+	c = b.start() // daemon restart, same boot
+	if st := c.Status(); !st.Locked {
+		t.Fatal("daemon restart lifted the lock")
+	}
+	if _, err := c.Try(code); !errors.Is(err, ErrLocked) {
+		t.Fatalf("right code after daemon restart: %v", err)
+	}
+	wrongs := 0
+	for _, e := range b.journal {
+		if strings.HasPrefix(e, EventWrong) {
+			wrongs++
+		}
+		if strings.Contains(e, code) || strings.Contains(e, Normalize(wrongCode(code))) {
+			t.Fatal("journal holds a typed code")
+		}
+	}
+	if wrongs != MaxWrong {
+		t.Fatalf("journal counts %d wrong codes", wrongs)
+	}
+	// The owner restarts the box: the screen opens with fewer tries.
+	b.boot = "boot-2"
+	c = b.start()
+	st := c.Status()
+	if st.Locked || st.TriesLeft != MaxWrong/2 {
+		t.Fatalf("after box restart: %+v", st)
+	}
+	for i := 0; i < MaxWrong/2; i++ {
+		c.Try(wrongCode(code))
+	}
+	if !c.Status().Locked {
+		t.Fatal("second lock")
+	}
+	b.boot = "boot-3"
+	c = b.start()
+	if st := c.Status(); st.TriesLeft != 1 {
+		t.Fatalf("third boot: %+v", st)
+	}
+	if _, err := c.Try(code); err != nil {
+		t.Fatalf("right code after restart: %v", err)
+	}
+}
+
+// A wrong count that cannot be saved locks the screen (fail closed).
+func TestUnsavableWrongCountLocks(t *testing.T) {
+	b, code := newBox(t)
+	c := b.start()
+	c.store = failStore{c.store}
+	if _, err := c.Try(wrongCode(code)); !errors.Is(err, ErrLocked) {
+		t.Fatalf("unsaved wrong code: %v", err)
+	}
+	c.store = b.st
+	if _, err := c.Try(code); !errors.Is(err, ErrLocked) {
+		t.Fatalf("right code after unsaved count: %v", err)
+	}
+}
+
+type failStore struct{ Store }
+
+func (failStore) Save([]byte) error { return errors.New("disk full") }
+
+func TestOpenUnsealedAndSealTwice(t *testing.T) {
+	st := change.FileStore{Path: filepath.Join(t.TempDir(), "claim.json")}
+	if _, err := Open(Config{Store: st, BootID: func() (string, error) { return "b", nil }}); !errors.Is(err, ErrNoCode) {
+		t.Fatalf("unsealed: %v", err)
+	}
+	if err := Seal(st, "not-a-code", nil, nil); err == nil {
+		t.Fatal("sealed a malformed code")
+	}
+	code, _ := NewCode(nil)
+	if err := Seal(st, code, nil, nil); err != nil {
+		t.Fatal(err)
+	}
+	if err := Seal(st, code, nil, nil); err == nil {
+		t.Fatal("resealed a sealed box")
+	}
+}
+
+// tryFresh presents one code to a box opened from sealed, so each try
+// meets a fresh count and the lockout never masks the compare.
+func tryFresh(t *testing.T, sealed []byte, code string) error {
+	t.Helper()
+	ms := &change.MemStore{}
+	if err := ms.Save(sealed); err != nil {
+		t.Fatal(err)
+	}
+	c, err := Open(Config{Store: ms, BootID: func() (string, error) { return "boot-1", nil }})
+	if err != nil {
+		t.Fatal(err)
+	}
+	_, err = c.Try(code)
+	return err
+}
+
+// Acceptance 3: a near miss is a wrong code. Only the whole code, every
+// symbol, claims the box (B1 of the #1067 review).
+func TestNearMissCodesRefused(t *testing.T) {
+	b, code := newBox(t)
+	sealed, err := b.st.Load()
+	if err != nil {
+		t.Fatal(err)
+	}
+	n := Normalize(code)
+	other := func(r byte) byte {
+		i := strings.IndexByte(alphabet, r)
+		return alphabet[(i+1)%len(alphabet)]
+	}
+	misses := map[string]string{
+		"last symbol changed": n[:CodeSymbols-1] + string(other(n[CodeSymbols-1])),
+		"15-symbol prefix":    n[:CodeSymbols-1],
+		"12-symbol prefix":    n[:12],
+		"one extra symbol":    n + "A",
+		"code twice":          n + n,
+		"empty":               "",
+	}
+	for i := 0; i < CodeSymbols; i++ {
+		m := []byte(n)
+		m[i] = other(m[i])
+		misses["symbol "+strconv.Itoa(i+1)+" changed"] = string(m)
+	}
+	for name, try := range misses {
+		if err := tryFresh(t, sealed, try); !errors.Is(err, ErrWrongCode) {
+			t.Fatalf("%s: %v", name, err)
+		}
+	}
+	// A few hundred random wrong codes, and one whose verifier shares its
+	// first byte with the right code's, so a short compare cannot pass.
+	var st state
+	if err := json.Unmarshal(sealed, &st); err != nil {
+		t.Fatal(err)
+	}
+	rng := mrand.New(mrand.NewSource(1067))
+	random := func() string {
+		s := make([]byte, CodeSymbols)
+		for i := range s {
+			s[i] = alphabet[rng.Intn(len(alphabet))]
+		}
+		return string(s)
+	}
+	for i := 0; i < 300; i++ {
+		if try := random(); try != n {
+			if err := tryFresh(t, sealed, try); !errors.Is(err, ErrWrongCode) {
+				t.Fatalf("random code %d: %v", i, err)
+			}
+		}
+	}
+	for i := 0; ; i++ {
+		if i > 1<<16 {
+			t.Fatal("no code with the same first verifier byte found")
+		}
+		try := random()
+		if try == n || verifier(st.Salt, try)[0] != st.Verifier[0] {
+			continue
+		}
+		if err := tryFresh(t, sealed, try); !errors.Is(err, ErrWrongCode) {
+			t.Fatalf("code sharing the first verifier byte: %v", err)
+		}
+		break
+	}
+	if err := tryFresh(t, sealed, code); err != nil {
+		t.Fatalf("right code: %v", err)
+	}
+}
+
+// lockedBox is a box whose screen locked in boot-1, and its state bytes.
+func lockedBox(t *testing.T) (*box, string, []byte) {
+	t.Helper()
+	b, code := newBox(t)
+	c := b.start()
+	for i := 0; i < MaxWrong; i++ {
+		c.Try(wrongCode(code))
+	}
+	if !c.Status().Locked {
+		t.Fatal("not locked")
+	}
+	raw, err := b.st.Load()
+	if err != nil {
+		t.Fatal(err)
+	}
+	return b, code, raw
+}
+
+type loadFail struct{ change.MemStore }
+
+func (*loadFail) Load() ([]byte, error) { return nil, errors.New("read error") }
+
+// Acceptance 3: a state the box cannot read is never an unclaimed or
+// unlocked box. Open fails, not ErrNoCode, and the lock on disk stays
+// (B2 of the #1067 review).
+func TestUnreadableStateKeepsLock(t *testing.T) {
+	b, code, raw := lockedBox(t)
+	boot2 := func() (string, error) { return "boot-2", nil }
+	refused := func(name string, err error) {
+		t.Helper()
+		if err == nil || errors.Is(err, ErrNoCode) {
+			t.Fatalf("%s: Open gave %v", name, err)
+		}
+	}
+
+	_, err := Open(Config{Store: &loadFail{}, BootID: boot2})
+	refused("read error", err)
+	_, err = Open(Config{Store: change.FileStore{Path: t.TempDir()}, BootID: boot2})
+	refused("state path is a directory", err)
+
+	partly := bytes.Replace(raw, []byte(`"wrong":`+strconv.Itoa(MaxWrong)), []byte(`"wrong":"`+strconv.Itoa(MaxWrong)+`"`), 1)
+	if bytes.Equal(partly, raw) {
+		t.Fatal("test setup: wrong count not found in state")
+	}
+	for name, bad := range map[string][]byte{
+		"empty":          {},
+		"truncated":      raw[:len(raw)/2],
+		"garbage":        []byte("\x00\xffclaim"),
+		"null":           []byte("null"),
+		"empty object":   []byte("{}"),
+		"partly decoded": partly,
+	} {
+		fs := change.FileStore{Path: filepath.Join(t.TempDir(), "claim.json")}
+		if err := os.WriteFile(fs.Path, bad, 0o600); err != nil {
+			t.Fatal(err)
+		}
+		_, err := Open(Config{Store: fs, BootID: boot2})
+		refused(name, err)
+		if got, _ := os.ReadFile(fs.Path); !bytes.Equal(got, bad) {
+			t.Fatalf("%s: Open rewrote the state", name)
+		}
+	}
+
+	_, err = Open(Config{Store: b.st, BootID: func() (string, error) { return "", errors.New("no boot_id") }})
+	refused("boot id error", err)
+	if got, _ := b.st.Load(); !bytes.Equal(got, raw) {
+		t.Fatal("boot id error: Open rewrote the state")
+	}
+	c := b.start() // still boot-1: the lock holds
+	if _, err := c.Try(code); !errors.Is(err, ErrLocked) {
+		t.Fatalf("right code after the failed opens: %v", err)
+	}
+}
