diff --git a/broker/firstboot/claim.go b/broker/firstboot/claim.go
new file mode 100644
index 000000000..40cdc90e1
--- /dev/null
+++ b/broker/firstboot/claim.go
@@ -0,0 +1,97 @@
+package firstboot
+
+import (
+	"errors"
+	"fmt"
+	"sync"
+
+	"github.com/ghbmrk/agentos/broker/card"
+	"github.com/ghbmrk/agentos/broker/claim"
+)
+
+// ErrUnclaimed is what ClaimedCard.Hold returns until a phone has claimed
+// the box with its sticker code (HW-10).
+var ErrUnclaimed = errors.New("firstboot: I am waiting to be claimed")
+
+// ClaimedCard is a preloaded box's first-boot path (HW-10): the Owner Card
+// step does not exist until the box is claimed, so no card, vault key or
+// approval-code seed is generated before the claim (HW-1). On a claimed
+// box it is the card step.
+type ClaimedCard struct {
+	cl  *claim.Claim
+	st  Store
+	cfg card.DisplayConfig
+
+	mu   sync.Mutex
+	step *CardStep
+}
+
+// NewClaimedCard builds the card step at once on a claimed box, and only
+// at the claim otherwise. st and cfg are NewCardStep's.
+func NewClaimedCard(cl *claim.Claim, st Store, cfg card.DisplayConfig) (*ClaimedCard, error) {
+	if cl == nil || st == nil || cfg.Provision == nil {
+		return nil, errors.New("firstboot: incomplete claim step config")
+	}
+	c := &ClaimedCard{cl: cl, st: st, cfg: cfg}
+	if cl.Claimed() {
+		if _, err := c.card(); err != nil {
+			return nil, err
+		}
+	}
+	return c, nil
+}
+
+// card builds the card step once the box is claimed; nil before.
+func (c *ClaimedCard) card() (*CardStep, error) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	if c.step != nil || !c.cl.Claimed() {
+		return c.step, nil
+	}
+	s, err := NewCardStep(c.st, c.cfg)
+	if err != nil {
+		return nil, err
+	}
+	c.step = s
+	return s, nil
+}
+
+// Status is the claim screen's state.
+func (c *ClaimedCard) Status() claim.Status { return c.cl.Status() }
+
+// Claim presents a sticker code. On the claim it returns the claiming
+// phone's token and starts the card step. If the card step cannot start,
+// the box is claimed all the same and the token is returned with the
+// error: Card and Hold retry it.
+func (c *ClaimedCard) Claim(code string) (string, error) {
+	tok, err := c.cl.Try(code)
+	if err != nil {
+		return "", err
+	}
+	if _, err := c.card(); err != nil {
+		return tok, fmt.Errorf("firstboot: claimed, but the card step did not start: %w", err)
+	}
+	return tok, nil
+}
+
+// Claimant reports whether tok names the phone that claimed the box: only
+// it is shown the Owner Card and continues setup.
+func (c *ClaimedCard) Claimant(tok string) bool { return c.cl.Claimant(tok) }
+
+// Card is the card step: nil before the claim.
+func (c *ClaimedCard) Card() *CardStep {
+	s, _ := c.card()
+	return s
+}
+
+// Hold returns ErrUnclaimed until the claim, then the card step's Hold.
+func (c *ClaimedCard) Hold() error {
+	if !c.cl.Claimed() {
+		return fmt.Errorf("%w: scan or type the claim code on my sticker", ErrUnclaimed)
+	}
+	s, err := c.card()
+	if err != nil {
+		return err
+	}
+	return s.Hold()
+}
diff --git a/broker/firstboot/claim_test.go b/broker/firstboot/claim_test.go
new file mode 100644
index 000000000..8b4992207
--- /dev/null
+++ b/broker/firstboot/claim_test.go
@@ -0,0 +1,151 @@
+package firstboot
+
+// REQ: HW-10, HW-1
+
+import (
+	"bytes"
+	"errors"
+	"io"
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/ghbmrk/agentos/broker/card"
+	"github.com/ghbmrk/agentos/broker/change"
+	"github.com/ghbmrk/agentos/broker/claim"
+	"github.com/ghbmrk/agentos/broker/recovery"
+)
+
+// canaryRand is the box's randomness in this test: a fixed canary stream
+// that counts what is drawn, so any secret made from it is both counted
+// and findable on disk.
+type canaryRand struct{ n int }
+
+var canary = []byte("CANARY-BOX-RAND-")
+
+func (c *canaryRand) Read(p []byte) (int, error) {
+	for i := range p {
+		p[i] = canary[(c.n+i)%len(canary)]
+	}
+	c.n += len(p)
+	return len(p), nil
+}
+
+// claimBoot is one start of a preloaded box from the partition at dir.
+type claimBoot struct {
+	step      *ClaimedCard
+	generated int
+	shown     *card.Card
+	b         *boot
+}
+
+func startPreloaded(t *testing.T, dir, bootID string, rnd io.Reader) *claimBoot {
+	t.Helper()
+	cl, err := claim.Open(claim.Config{
+		Store:  change.FileStore{Path: filepath.Join(dir, "var", "lib", "agentos", "claim.json")},
+		BootID: func() (string, error) { return bootID, nil },
+		Rand:   rnd,
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	cb := &claimBoot{b: &boot{t: t, dir: dir}}
+	cb.step, err = NewClaimedCard(cl, change.FileStore{Path: filepath.Join(dir, "var", "lib", "agentos", "firstboot-card.json")},
+		card.DisplayConfig{
+			Rand: rnd,
+			Generate: func(r io.Reader) (*card.Card, error) {
+				cb.generated++
+				c, err := card.Generate(r)
+				if err == nil {
+					cp := *c
+					cp.GridSeed = bytes.Clone(c.GridSeed)
+					cb.shown = &cp
+				}
+				return c, err
+			},
+			Provision: cb.b.provision,
+		})
+	if err != nil {
+		t.Fatal(err)
+	}
+	return cb
+}
+
+// Acceptance 2: before the claim, a scan of the disk finds no vault key,
+// card text or approval-code seed. The box draws no randomness for a
+// secret before the claim (the canary stream is untouched), no card is
+// generated, and no vault exists; the card made at the claim was nowhere
+// on the pre-claim disk.
+func TestNoSecretBeforeClaim(t *testing.T) {
+	dir := t.TempDir()
+	for _, d := range []string{"var/lib/agentos", "var/log/agentos", "egress"} {
+		if err := os.MkdirAll(filepath.Join(dir, d), 0o700); err != nil {
+			t.Fatal(err)
+		}
+	}
+	captureLogs(t, dir)
+	code, err := claim.NewCode(nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := claim.Seal(change.FileStore{Path: filepath.Join(dir, "var", "lib", "agentos", "claim.json")}, code, nil, nil); err != nil {
+		t.Fatal(err)
+	}
+	rnd := &canaryRand{}
+	cb := startPreloaded(t, dir, "boot-1", rnd)
+	if err := cb.step.Hold(); !errors.Is(err, ErrUnclaimed) {
+		t.Fatalf("hold before claim: %v", err)
+	}
+	if cb.step.Card() != nil {
+		t.Fatal("card step before claim")
+	}
+	bad := []byte(code)
+	bad[0] ^= 1
+	if _, err := cb.step.Claim(string(bad)); !errors.Is(err, claim.ErrWrongCode) {
+		t.Fatalf("wrong code: %v", err)
+	}
+	cb = startPreloaded(t, dir, "boot-2", rnd)
+
+	if rnd.n != 0 || cb.generated != 0 {
+		t.Fatalf("before the claim the box drew %d random bytes and made %d cards", rnd.n, cb.generated)
+	}
+	for _, f := range []string{"egress/vault", "egress/vault.keys", "var/lib/agentos/firstboot-card.json"} {
+		if _, err := os.Stat(filepath.Join(dir, f)); !errors.Is(err, os.ErrNotExist) {
+			t.Fatalf("%s exists before the claim", f)
+		}
+	}
+	snap := t.TempDir()
+	if err := os.CopyFS(snap, os.DirFS(dir)); err != nil {
+		t.Fatal(err)
+	}
+	s, err := recovery.NewScanner([]recovery.Needle{{Name: "box randomness", Value: canary}})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if found, skipped, err := s.Tree(snap); err != nil || len(found)+len(skipped) > 0 {
+		t.Fatalf("canary before claim: %v %v %v", found, skipped, err)
+	}
+
+	tok, err := cb.step.Claim(code)
+	if err != nil {
+		t.Fatalf("claim: %v", err)
+	}
+	if !cb.step.Claimant(tok) || cb.step.Card() == nil || cb.generated != 1 || rnd.n == 0 {
+		t.Fatal("claim did not start the card step from the box's randomness")
+	}
+	if err := cb.step.Hold(); !errors.Is(err, ErrCardPending) {
+		t.Fatalf("hold after claim: %v", err)
+	}
+	// The card made at the claim was not on the disk before it.
+	scan(t, snap, cb.shown)
+
+	// A second phone, and a restart, find the box claimed; the card step
+	// comes back on its own.
+	again := startPreloaded(t, dir, "boot-3", &canaryRand{})
+	if _, err := again.step.Claim(code); !errors.Is(err, claim.ErrAlreadyClaimed) {
+		t.Fatalf("second claim: %v", err)
+	}
+	if again.step.Card() == nil || !again.step.Claimant(tok) {
+		t.Fatal("claimed box lost its card step or claimant on restart")
+	}
+}
